/**
 * Bundles packages/storage/drizzle/*.sql (written by drizzle-kit) into src/migrations.generated.ts, because the
 * browser worker cannot read files. Run through `pnpm db:generate`; check the generated file in.
 */
import { readdirSync, readFileSync, writeFileSync } from 'node:fs';
import { dirname, join } from 'node:path';
import { fileURLToPath } from 'node:url';

const storage = join(dirname(fileURLToPath(import.meta.url)), '..', 'packages', 'storage');
const files = readdirSync(join(storage, 'drizzle'))
  .filter((file) => /^\d{4}_.*\.sql$/.test(file))
  .sort();

const migrations = files.map((file) => ({
  id: Number(file.slice(0, 4)),
  name: file.slice(5, -'.sql'.length),
  statements: readFileSync(join(storage, 'drizzle', file), 'utf8')
    .split('--> statement-breakpoint')
    .map((statement) => statement.trim())
    .filter(Boolean),
}));

const body = `// Generated by \`pnpm db:generate\` from packages/storage/drizzle/*.sql. Do not edit.
export type Migration = { id: number; name: string; statements: string[] };

export const MIGRATIONS: Migration[] = ${JSON.stringify(migrations, null, 2)};
`;
writeFileSync(join(storage, 'src', 'migrations.generated.ts'), body);
console.log(`db:bundle wrote ${migrations.length} migration(s)`);
